      SdkModel.to_h(self, FIELDS)
    end

    def to_json(*args)
      to_h.to_json(*args)
    end
  end

  # Internal model hydration metadata.
  class SdkInternalPublicEventMetadata
    FIELDS = {}.freeze
    REQUIRED_FIELDS = %i[].freeze
    DECODERS = {}.freeze
  end
end
